class Node { constructor(val, next = null) { this.val = val; this.next = next; } }
class List {
  head = null; size = 0;
  unshift(v) { this.head = new Node(v, this.head); this.size++; }
  toArray() { const out = []; for (let n = this.head; n; n = n.next) out.push(n.val); return out; }
}
const l = new List();
l.unshift(1); l.unshift(2); l.unshift(3);
console.log(l.toArray().join('->'), l.size);

