const str = h => { const o = []; for (; h; h = h.next) o.push(h.val); return o.join(''); };
function reverse(head) {
  let prev = null;
  while (head) { const next = head.next; head.next = prev; prev = head; head = next; }
  return prev;
}
const h = mk([1, 2, 3, 4]);
const r = reverse(h);
console.log(str(r), str(h));

const mk = arr => arr.reduceRight((next, val) => ({ val, next }), null);
function middle(head) {
  let s = head, f = head;
  while (f && f.next) { s = s.next; f = f.next.next; }
  return s.val;
}
console.log(middle(mk([1, 2, 3, 4, 5])), middle(mk([1, 2, 3, 4])));

