const root = n(1, n(2, n(4), n(5)), n(3));
const pre = [], ino = [], post = [];
(function walk(t) {
  if (!t) return;
  pre.push(t.v); walk(t.l); ino.push(t.v); walk(t.r); post.push(t.v);
})(root);
console.log(pre.join(''), ino.join(''), post.join(''));

