const n = (v, l = null, r = null) => ({ v, l, r });
const root = n(1, n(2, n(4)), n(3, null, n(5)));
const res = [];
let q = [root], ltr = true;
while (q.length) {
  const vals = q.map(t => t.v);
  res.push((ltr ? vals : vals.reverse()).join(''));
  ltr = !ltr;
  q = q.flatMap(t => [t.l, t.r].filter(Boolean));
}
console.log(res.join(','));

