function kth(root, k) {
  const st = []; let cur = root;
  while (cur || st.length) {
    while (cur) { st.push(cur); cur = cur.l; }
    cur = st.pop();
    if (--k === 0) return cur.v;
    cur = cur.r;
  }
  return null;
}
